// Generated by MCSuperMods from the msm/<namespace>/biome_addition/*.json definitions.
package msm_test;

import java.util.ArrayList;
import java.util.List;
import java.util.function.Predicate;
import net.fabricmc.fabric.api.biome.v1.BiomeModifications;
import net.fabricmc.fabric.api.biome.v1.BiomeSelectionContext;
import net.fabricmc.fabric.api.biome.v1.BiomeSelectors;
import net.fabricmc.fabric.api.biome.v1.ModificationPhase;
import net.fabricmc.fabric.api.event.lifecycle.v1.ServerLifecycleEvents;
import net.minecraft.core.HolderLookup;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.core.registries.Registries;
import net.minecraft.resources.Identifier;
import net.minecraft.resources.ResourceKey;
import net.minecraft.server.MinecraftServer;
import net.minecraft.tags.TagKey;
import net.minecraft.util.valueproviders.ConstantInt;
import net.minecraft.util.valueproviders.IntProvider;
import net.minecraft.util.valueproviders.UniformInt;
import net.minecraft.world.entity.MobCategory;
import net.minecraft.world.level.biome.Biome;
import net.minecraft.world.level.biome.MobSpawnSettings;
import net.minecraft.world.level.levelgen.GenerationStep;
import net.minecraft.world.level.levelgen.placement.PlacedFeature;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Additions to vanilla biomes: placed features and natural spawns, added by Fabric when a server starts, so they are
 * fixed per world load and only new chunks get the features. A placed feature, biome, tag or entity type that does
 * not exist is a warning after start-up and is not added.
 */
public final class ModWorldgen {
    private static final Logger LOGGER = LoggerFactory.getLogger("msm_test");

    private ModWorldgen() {}

    /** Registers every biome addition and the check of their ids after start-up. */
    public static void register() {
        addBadlandsTag();
        addDesertFox();
        addMissingFeature();
        addPlainsOre();
        ServerLifecycleEvents.SERVER_STARTED.register(server -> {
            warnUnknownBiome(server, "msm/msm_test/biome_addition/badlands_tag.json", "#minecraft:is_badlands");
            warnUnknownFeature(server, "msm/msm_test/biome_addition/badlands_tag.json", "msm_test:addition_tag_ore");
            warnUnknownBiome(server, "msm/msm_test/biome_addition/desert_fox.json", "minecraft:desert");
            warnUnknownEntity("msm/msm_test/biome_addition/desert_fox.json", "minecraft:fox");
            warnUnknownBiome(server, "msm/msm_test/biome_addition/missing_feature.json", "minecraft:savanna");
            warnUnknownFeature(server, "msm/msm_test/biome_addition/missing_feature.json", "msm_test:missing_feature");
            warnUnknownEntity("msm/msm_test/biome_addition/missing_feature.json", "msm_test:missing_mob");
            warnUnknownBiome(server, "msm/msm_test/biome_addition/plains_ore.json", "minecraft:plains");
            warnUnknownFeature(server, "msm/msm_test/biome_addition/plains_ore.json", "msm_test:addition_ore");
        });
    }

    /** {@code msm_test:badlands_tag} (msm/msm_test/biome_addition/badlands_tag.json). */
    private static void addBadlandsTag() {
        Predicate<BiomeSelectionContext> selector = biomes("#minecraft:is_badlands");
        feature(Identifier.fromNamespaceAndPath("msm_test", "biome_addition/badlands_tag/feature/0"), selector, GenerationStep.Decoration.UNDERGROUND_DECORATION,
                Identifier.fromNamespaceAndPath("msm_test", "addition_tag_ore"));
    }

    /** {@code msm_test:desert_fox} (msm/msm_test/biome_addition/desert_fox.json). */
    private static void addDesertFox() {
        Predicate<BiomeSelectionContext> selector = biomes("minecraft:desert");
        spawn(Identifier.fromNamespaceAndPath("msm_test", "biome_addition/desert_fox/spawn/0"), selector, MobCategory.CREATURE,
                Identifier.fromNamespaceAndPath("minecraft", "fox"), 7, 1, 3); // weight, min_group, max_group
    }

    /** {@code msm_test:missing_feature} (msm/msm_test/biome_addition/missing_feature.json). */
    private static void addMissingFeature() {
        Predicate<BiomeSelectionContext> selector = biomes("minecraft:savanna");
        feature(Identifier.fromNamespaceAndPath("msm_test", "biome_addition/missing_feature/feature/0"), selector, GenerationStep.Decoration.VEGETAL_DECORATION,
                Identifier.fromNamespaceAndPath("msm_test", "missing_feature"));
        spawn(Identifier.fromNamespaceAndPath("msm_test", "biome_addition/missing_feature/spawn/0"), selector, MobCategory.MONSTER,
                Identifier.fromNamespaceAndPath("msm_test", "missing_mob"), 1, 1, 1); // weight, min_group, max_group
    }

    /** {@code msm_test:plains_ore} (msm/msm_test/biome_addition/plains_ore.json). */
    private static void addPlainsOre() {
        Predicate<BiomeSelectionContext> selector = biomes("minecraft:plains");
        feature(Identifier.fromNamespaceAndPath("msm_test", "biome_addition/plains_ore/feature/0"), selector, GenerationStep.Decoration.UNDERGROUND_ORES,
                Identifier.fromNamespaceAndPath("msm_test", "addition_ore"));
    }

    /** The union of biome ids and {@code #}-prefixed biome tags (the runtime's BiomeSelection). */
    private static Predicate<BiomeSelectionContext> biomes(String... entries) {
        Predicate<BiomeSelectionContext> selector = context -> false;
        List<ResourceKey<Biome>> keys = new ArrayList<>();
        for (String entry : entries) {
            if (entry.startsWith("#")) {
                selector = selector.or(BiomeSelectors.tag(TagKey.create(Registries.BIOME, Identifier.parse(entry.substring(1)))));
            } else {
                keys.add(ResourceKey.create(Registries.BIOME, Identifier.parse(entry)));
            }
        }
        if (!keys.isEmpty()) {
            selector = selector.or(BiomeSelectors.includeByKey(keys));
        }
        return selector;
    }

    /**
     * Adds a placed feature to the selected biomes when a server starts. Fabric's addFeature throws for a key that is not
     * in the registry, which would stop the server, so the key is looked up first and a missing one is skipped.
     */
    private static void feature(Identifier modification, Predicate<BiomeSelectionContext> selector, GenerationStep.Decoration step, Identifier feature) {
        ResourceKey<PlacedFeature> key = ResourceKey.create(Registries.PLACED_FEATURE, feature);
        BiomeModifications.create(modification).add(ModificationPhase.ADDITIONS, selector, (selection, context) -> {
            if (selection.getRegistryAccess().lookupOrThrow(Registries.PLACED_FEATURE).get(key).isPresent()) {
                context.getGenerationSettings().addFeature(step, key);
            }
        });
    }

    /**
     * Adds a natural spawn to the selected biomes when a server starts; the entity type is resolved then, once every mod
     * has registered its types, and a missing one is skipped. addSpawn(MobCategory, SpawnerData, int) is deprecated by
     * Fabric in favour of overloads that take the category from the type; the definition names its category.
     */
    @SuppressWarnings("deprecation")
    private static void spawn(Identifier modification, Predicate<BiomeSelectionContext> selector, MobCategory category, Identifier entity,
            int weight, int minGroup, int maxGroup) {
        IntProvider count = minGroup == maxGroup ? ConstantInt.of(minGroup) : UniformInt.of(minGroup, maxGroup);
        BiomeModifications.create(modification).add(ModificationPhase.ADDITIONS, selector, context -> BuiltInRegistries.ENTITY_TYPE.getOptional(entity)
                .ifPresent(type -> context.getMobSpawnSettings().addSpawn(category, new MobSpawnSettings.SpawnerData(type, count), weight)));
    }

    /** Warns about a biome or {@code #}-prefixed biome tag that does not exist on the running server. */
    private static void warnUnknownBiome(MinecraftServer server, String file, String entry) {
        HolderLookup.RegistryLookup<Biome> biomes = server.registryAccess().lookupOrThrow(Registries.BIOME);
        boolean known = entry.startsWith("#")
                ? biomes.get(TagKey.create(Registries.BIOME, Identifier.parse(entry.substring(1)))).isPresent()
                : biomes.get(ResourceKey.create(Registries.BIOME, Identifier.parse(entry))).isPresent();
        if (!known) {
            LOGGER.warn("{}: unknown biome in biomes {}", file, entry);
        }
    }

    /** Warns about a placed feature that does not exist on the running server; it is not added. */
    private static void warnUnknownFeature(MinecraftServer server, String file, String id) {
        if (server.registryAccess().lookupOrThrow(Registries.PLACED_FEATURE).get(ResourceKey.create(Registries.PLACED_FEATURE, Identifier.parse(id))).isEmpty()) {
            LOGGER.warn("{}: unknown placed feature {}; the feature is not added", file, id);
        }
    }

    /** Warns about an entity type that no mod registered; the spawn is not added. */
    private static void warnUnknownEntity(String file, String id) {
        if (!BuiltInRegistries.ENTITY_TYPE.containsKey(Identifier.parse(id))) {
            LOGGER.warn("{}: unknown entity type {}; the spawn is not added", file, id);
        }
    }
}
